// Blocks to read: after the cursor, up to head-3 (reorg margin), at most 10 per run so a
// restart catches up at 2x real time without hammering a free RPC. One JSON-RPC batch does it all.
const plan = $('Plan').first().json.plan;
const res = JSON.parse($input.first().json.data);
if (!plan || !plan.ready) return [];          // Market Sentinel has no ETH/BTC price yet
if (!res || !res.result) throw new Error('eth_blockNumber failed: ' + JSON.stringify(res && res.error || res).slice(0, 200));
const safe = parseInt(res.result, 16) - 3;
const MAX = 10;
const from = plan.cursor == null ? safe : Number(plan.cursor) + 1;
const through = Math.min(safe, from + MAX - 1);
if (from > through) return [];
const hex = n => '0x' + n.toString(16);
const body = [];
for (let n = from; n <= through; n++) body.push({ jsonrpc: '2.0', id: n, method: 'eth_getBlockByNumber', params: [hex(n), true] });
body.push({ jsonrpc: '2.0', id: 0, method: 'eth_getLogs', params: [{
  fromBlock: hex(from), toBlock: hex(through),
  address: plan.assets.filter(a => a.contract).map(a => a.contract),
  topics: ['0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef'],   // Transfer(address,address,uint256)
}] });
return [{ json: { from, through, body } }];

// Native ETH from block bodies, ERC-20s from Transfer logs. Amounts stay exact (BigInt -> decimal string);
// only moves above each asset's store floor (from chain.plan) leave n8n.
const plan = $('Plan').first().json.plan;
const pick = $('Pick blocks').first().json;
const res = JSON.parse($input.first().json.data);
if (!Array.isArray(res)) throw new Error('RPC batch failed: ' + JSON.stringify(res).slice(0, 200));
const byId = new Map(res.map(r => [Number(r.id), r]));
const asset = Object.fromEntries(plan.assets.map(a => [a.asset, a]));
const byContract = Object.fromEntries(plan.assets.filter(a => a.contract).map(a => [a.contract, a]));
const floorRaw = a => BigInt(Math.floor(a.floor * 1e6)) * 10n ** BigInt(a.decimals) / 1000000n;
const units = (raw, dec) => {
  const s = raw.toString().padStart(dec + 1, '0');
  const int = s.slice(0, s.length - dec), frac = s.slice(s.length - dec).replace(/0+$/, '');
  return frac ? `${int}.${frac}` : int;
};
const addr = topic => '0x' + topic.slice(26).toLowerCase();
const blockTs = new Map(), transfers = [];
const ethFloor = floorRaw(asset.ETH);
for (let n = pick.from; n <= pick.through; n++) {
  const r = byId.get(n);
  if (!r || r.error || !r.result) throw new Error(`Block ${n}: ` + JSON.stringify(r ? r.error : 'missing').slice(0, 200));
  const t = parseInt(r.result.timestamp, 16) * 1000;
  blockTs.set(n, t);
  for (const tx of r.result.transactions || []) {
    if (!tx.to) continue;                                                // contract creation
    const v = BigInt(tx.value);
    if (v < ethFloor) continue;
    transfers.push({ h: tx.hash, i: -1, a: 'ETH', q: units(v, 18), t, b: n, f: [tx.from.toLowerCase()], o: [tx.to.toLowerCase()] });
  }
}
const logs = byId.get(0);
if (!logs || logs.error || !Array.isArray(logs.result)) throw new Error('eth_getLogs: ' + JSON.stringify(logs ? logs.error : 'missing').slice(0, 200));
for (const l of logs.result) {
  const a = byContract[String(l.address).toLowerCase()];
  if (!a || l.removed || !l.topics || l.topics.length !== 3 || !l.data || l.data.length < 66) continue;
  const v = BigInt(l.data.slice(0, 66));
  if (v < floorRaw(a)) continue;
  const n = parseInt(l.blockNumber, 16);
  transfers.push({ h: l.transactionHash, i: parseInt(l.logIndex, 16), a: a.asset, q: units(v, a.decimals),
                   t: blockTs.get(n), b: n, f: [addr(l.topics[1])], o: [addr(l.topics[2])] });
}
return [{ json: { through: pick.through, transfers } }];

// Telegram gets severity HIGH only; the Constellation gets everything. HTML parse mode, all text escaped.
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const LINK = { btc: h => `https://mempool.space/tx/${h}`, eth: h => `https://etherscan.io/tx/${h}` };
return $input.all().filter(i => i.json.severity === 'high').map(({ json: w }) => {
  const when = new Date(w.ts).toLocaleString('en-GB', { timeZone: 'Asia/Kuwait', hour12: false });
  const text = `🐋 <b>OMEGA WHALE · ${esc(String(w.chain).toUpperCase())}</b> · HIGH\n${esc(w.reason)}\n` +
    `<a href="${esc(LINK[w.chain](w.tx_hash))}">View transaction</a>\n<i>${esc(when)} Kuwait</i>`;
  return { json: { text } };
});
